# FEAST n=20: reconstruct the smooth, single-master-trace optimization in R.
# No radial mirror symmetry is imposed. The entire ensemble is generated by
# rotations and two-beat phase shifts. Passing partners change by one beat.
#
# Install: install.packages(c('ggplot2','gganimate','gifski'))
# Run: Rscript feast_n20_reconstruction_gganimate.R
# Optional warm start: put feast_unconstrained_n20_trace.csv in same directory,
# or set warm_start_file to any CSV with radial_ft,tangential_ft columns.
# Outputs: clockwise and counterclockwise GIFs, optimized master CSV, diagnostics CSV.
#
# IMPORTANT: this reconstructs the MODEL described in feast_report.md; the
# original optimizer coefficients/coordinates from yesterday are not available.

suppressPackageStartupMessages({
  library(ggplot2)
  library(gganimate)
})
set.seed(20261108)

n <- 20L
personal_radius <- 3
# The reconstructed report's home radius; adjacent home spacing ~= 7 ft.
home_radius <- 22.374
samples_per_beat <- 4L
frames_per_beat <- 6L
warm_start_file <- 'feast_unconstrained_n20_trace.csv'

# All weights are editable. The report did NOT archive all fitted coefficients.
w <- list(home_radial=.08, home_tangential=.50,
          speed=.23, acceleration=.32,
          short_under_6=150, preferred_under_9=0, # set preferred_under_9=2 to bias longer
          throw_over_10=3, throw_over_12=100,
          collision=85)
soft_collision_distance <- 6.18 # desired center separation, with safety margin

# Beat t=0: partner j=(t-i) mod n, with zero-based juggler numbers.
pair_beat <- integer(0); pair_i <- integer(0); pair_j <- integer(0)
for (t in 0:(n-1)) for (i in 0:(n-1)) {
  j <- (t-i) %% n
  if (i < j) {
    pair_beat <- c(pair_beat,t); pair_i <- c(pair_i,i+1L); pair_j <- c(pair_j,j+1L)
  }
}
stopifnot(length(pair_i) == n*(n-1)/2)
all_pairs <- combn(n,2)

# Analytic matrix for cyclic cubic interpolation of the 20 master beat positions.
# Every row represents a (sample time, juggler) combination, with time major.
periodic_basis <- lapply(seq_len(n),function(k) {
  y <- as.numeric(seq_len(n)==k)
  splinefun(0:n,c(y,y[1]),method='periodic')
})
make_interpolator <- function(times) {
  S <- length(times)
  shifted <- numeric(S*n)
  idx <- integer(S*n)
  r <- 0L
  for (s in seq_len(S)) for (i in seq_len(n)) {
    r <- r+1L
    shifted[r] <- (times[s]-2*(i-1L)) %% n
    idx[r] <- i
  }
  C <- vapply(periodic_basis, function(f) f(shifted), numeric(S*n))
  list(C=C, index=idx, times=times, S=S)
}

sample_times <- (0:(n*samples_per_beat-1))/samples_per_beat
sampling <- make_interpolator(sample_times)
S <- sampling$S
C <- sampling$C
jidx <- sampling$index
cs <- cos(2*pi*(jidx-1)/n)
sn <- sin(2*pi*(jidx-1)/n)
rows_i <- rep((0:(S-1))*n,each=ncol(all_pairs))+rep(all_pairs[1,],times=S)
rows_j <- rep((0:(S-1))*n,each=ncol(all_pairs))+rep(all_pairs[2,],times=S)
beatrow <- function(t,i) t*samples_per_beat*n+i
p_rows_i <- mapply(beatrow,pair_beat,pair_i)
p_rows_j <- mapply(beatrow,pair_beat,pair_j)

# Positions and analytic reverse-mode gradient w.r.t. master control points.
positions <- function(q, setup=sampling) {
  l <- setup$C %*% q
  a <- 2*pi*(setup$index-1)/n
  cbind(cos(a)*l[,1]+sin(a)*l[,2], -sin(a)*l[,1]+cos(a)*l[,2])
}

# Return objective and analytic gradient; x is the vectorized 20x2 master trace.
objective_gradient <- function(z) {
  q <- matrix(z,n,2)
  home <- cbind(rep(home_radius,n),rep(0,n))
  dq <- q-home
  E <- w$home_radial*sum(dq[,1]^2)+w$home_tangential*sum(dq[,2]^2)
  G <- cbind(2*w$home_radial*dq[,1],2*w$home_tangential*dq[,2])

  prev <- c(n,1:(n-1)); nexti <- c(2:n,1)
  diff <- q-q[prev,,drop=FALSE]
  E <- E+w$speed*sum(diff^2)
  G <- G+2*w$speed*(2*q-q[prev,,drop=FALSE]-q[nexti,,drop=FALSE])

  accel <- q[nexti,,drop=FALSE]-2*q+q[prev,,drop=FALSE]
  E <- E+w$acceleration*sum(accel^2)
  G <- G+2*w$acceleration*(accel[nexti,,drop=FALSE]-2*accel+accel[prev,,drop=FALSE])

  X <- positions(q)
  GX <- matrix(0,nrow(X),2)
  add_grad <- function(row_a,row_b,gg) {
    groups <- c(row_a,row_b)
    delta <- rbind(gg,-gg)
    summed <- rowsum(delta,groups,reorder=TRUE)
    idx <- as.integer(rownames(summed))
    GX[idx,] <<- GX[idx,,drop=FALSE]+summed
  }

  dv <- X[p_rows_i,,drop=FALSE]-X[p_rows_j,,drop=FALSE]
  d <- pmax(sqrt(rowSums(dv^2)),1e-9)
  under6 <- pmax(6-d,0); under9 <- pmax(9-d,0)
  over10 <- pmax(d-10,0); over12 <- pmax(d-12,0)
  E <- E+w$short_under_6*sum(under6^2)+w$preferred_under_9*sum(under9^2)+
    w$throw_over_10*sum(over10^2)+w$throw_over_12*sum(over12^2)
  deriv <- (-2*w$short_under_6*under6-2*w$preferred_under_9*under9+
             2*w$throw_over_10*over10+2*w$throw_over_12*over12)/d
  add_grad(p_rows_i,p_rows_j,dv*deriv)

  sep <- X[rows_i,,drop=FALSE]-X[rows_j,,drop=FALSE]
  dist <- pmax(sqrt(rowSums(sep^2)),1e-9)
  violation <- pmax(soft_collision_distance-dist,0)
  E <- E+w$collision/samples_per_beat*sum(violation^2)
  deriv <- (-2*w$collision/samples_per_beat)*violation/dist
  add_grad(rows_i,rows_j,sep*deriv)

  # Rotate Cartesian position gradients back into local radial/tangential coordinates.
  gl <- cbind(cs*GX[,1]-sn*GX[,2],sn*GX[,1]+cs*GX[,2])
  G <- G+crossprod(C,gl)
  list(value=as.numeric(E),gradient=as.vector(G))
}

# Cache value and gradient because optim's fn/gr can ask for the same z.
cache <- new.env(parent=emptyenv()); cache$z <- NULL
cached <- function(z) {
  if (is.null(cache$z) || !identical(z,cache$z)) {
    cache$z <- z
    cache$result <- objective_gradient(z)
  }
  cache$result
}

initial_master <- function(seed) {
  set.seed(seed)
  k <- 0:(n-1)
  rad <- home_radius-2.8*cos(2*pi*k/n)-1.2*cos(4*pi*k/n)+.6*cos(6*pi*k/n)
  tan <- 4.5*sin(2*pi*k/n)+2.8*sin(4*pi*k/n)
  cbind(rad,tan)+matrix(rnorm(2*n,sd=.7),n,2)
}

starts <- list(initial_master(1),initial_master(7),initial_master(23))
if (file.exists(warm_start_file)) {
  warm <- tryCatch(read.csv(warm_start_file),error=function(e) NULL)
  if (!is.null(warm) && nrow(warm)==n && ncol(warm)>=2) {
    starts <- c(list(as.matrix(warm[,1:2])),starts)
    cat('Using warm-start trace from',warm_start_file,'\n')
  }
}

best <- NULL
for (k in seq_along(starts)) {
  cache$z <- NULL
  fit <- optim(as.vector(starts[[k]]),fn=function(z) cached(z)$value,
               gr=function(z) as.vector(cached(z)$gradient),method='L-BFGS-B',
               control=list(maxit=800,factr=1e7,pgtol=1e-5))
  cat(sprintf('Start %d: objective %.4f, convergence %d\n',k,fit$value,fit$convergence))
  if (is.null(best) || fit$value<best$value) best <- fit
}
q <- matrix(best$par,n,2)
write.csv(data.frame(radial_ft=q[,1],tangential_ft=q[,2]),
          'feast_n20_reconstructed_master.csv',row.names=FALSE)

# Dense diagnostics: exact sampled spacing, total trace length and peak acceleration.
dense <- make_interpolator((0:(n*40-1))/40)
D <- positions(q,dense)
min_spacing <- Inf
for (s in seq_len(dense$S)) {
  ri <- (s-1)*n+all_pairs[1,]; rj <- (s-1)*n+all_pairs[2,]
  min_spacing <- min(min_spacing,sqrt(rowSums((D[ri,,drop=FALSE]-D[rj,,drop=FALSE])^2)))
}
beatX <- positions(q,make_interpolator(0:(n-1)))
throw_length <- numeric(length(pair_i))
closest_bystander <- Inf
obstructed <- 0L
for (k in seq_along(pair_i)) {
  t <- pair_beat[k]; i <- pair_i[k]; j <- pair_j[k]
  a <- beatX[t*n+i,]; b <- beatX[t*n+j,]
  v <- b-a
  throw_length[k] <- sqrt(sum(v*v))
  others <- setdiff(seq_len(n),c(i,j))
  xx <- beatX[t*n+others,,drop=FALSE]
  d <- sweep(xx,2,a,'-')
  projection <- pmax(0,pmin(1,as.vector(d%*%v/sum(v*v))))
  nearest <- d-projection %o% v
  dist <- sqrt(rowSums(nearest^2))
  closest_bystander <- min(closest_bystander,dist)
  if (min(dist)<personal_radius) obstructed <- obstructed+1L
}

# Trace length and RMS acceleration in local coordinates, using dense spline points.
master_dense <- sapply(periodic_basis, function(f) f((0:(n*100-1))/100)) %*% q
walk <- sum(sqrt(rowSums((master_dense-master_dense[c(2:nrow(master_dense),1),])^2)))
# Second derivative: use a periodic central finite difference at 1/100 beat.
second <- (master_dense[c(2:nrow(master_dense),1),]-2*master_dense+
             master_dense[c(nrow(master_dense),1:(nrow(master_dense)-1)),])/(.01^2)
rms_accel <- sqrt(mean(rowSums(second^2)))
report <- data.frame(objective=best$value,walking_ft=walk,
                     minimum_throw_ft=min(throw_length),mean_throw_ft=mean(throw_length),
                     maximum_throw_ft=max(throw_length),throws_under_6=sum(throw_length<6),
                     minimum_center_spacing_ft=min_spacing,
                     minimum_pass_bystander_center_ft=closest_bystander,
                     obstructed_passes=obstructed,rms_acceleration_ft_per_beat_squared=rms_accel)
print(report)
write.csv(report,'feast_n20_reconstructed_diagnostics.csv',row.names=FALSE)
if (min_spacing<6) warning('Personal discs overlap between passing beats; adjust weights.')
if (obstructed>0) warning('Some straight passes cross bystander discs; this is measured but NOT penalized by the objective.')

# gganimate visual design faithful to the reference: colored whole-cycle traces,
# small marked dots at EVERY passing beat, grey crosses at home, numbered discs.
# Frame positions are spline-derived, NOT gganimate cubic-in-out tweening.
colors <- grDevices::hcl.colors(n,'Dynamic')
trace_times <- (0:(n*80-1))/80
trace_positions <- positions(q,make_interpolator(trace_times))
static_traces <- data.frame(time=rep(trace_times,each=n),
                            juggler=factor(rep(seq_len(n),times=length(trace_times))),
                            x=trace_positions[,1],y=trace_positions[,2])
beat_dots <- data.frame(juggler=factor(rep(seq_len(n),times=n)),
                        x=beatX[,1],y=beatX[,2])
homes <- data.frame(juggler=factor(seq_len(n)),
                    x=home_radius*cos(2*pi*(0:(n-1))/n),
                    y=-home_radius*sin(2*pi*(0:(n-1))/n))

# Display straight-line passes exactly on beat frames (not continuously in between).
make_frames <- function(reverse_time=FALSE) {
  frames <- n*frames_per_beat
  phase <- (0:(frames-1))/frames_per_beat
  actual <- if (reverse_time) (-phase) %% n else phase
  X <- positions(q,make_interpolator(actual))
  moving <- data.frame(frame=rep(seq_len(frames),each=n),
                       juggler=factor(rep(seq_len(n),times=frames),levels=seq_len(n)),
                       x=X[,1],y=X[,2])
  # Thin polygon can make the collective oscillating envelope visible.
  envelope <- moving
  disks <- data.frame()
  # Personal circles as 32-point open outlines.
  ph <- seq(0,2*pi,length.out=33)
  disklist <- vector('list',frames*n)
  idx <- 0
  for (f in seq_len(frames)) for (i in seq_len(n)) {
    idx <- idx+1L
    x0 <- X[(f-1)*n+i,1]; y0 <- X[(f-1)*n+i,2]
    disklist[[idx]] <- data.frame(frame=f,juggler=factor(i,levels=seq_len(n)),
                                  x=x0+personal_radius*cos(ph),
                                  y=y0+personal_radius*sin(ph))
  }
  disks <- do.call(rbind,disklist)
  segments <- vector('list',frames)
  for (f in seq_len(frames)) {
    if ((f-1)%%frames_per_beat !=0) next
    t <- round(actual[f]) %% n
    selected <- which(pair_beat==t)
    rows1 <- (f-1)*n+pair_i[selected]
    rows2 <- (f-1)*n+pair_j[selected]
    segments[[f]] <- data.frame(frame=f,x=X[rows1,1],y=X[rows1,2],
                                 xend=X[rows2,1],yend=X[rows2,2])
  }
  segments <- do.call(rbind,segments)
  direction <- if (reverse_time) 'counterclockwise' else 'clockwise'
  # Fixed common extent and scale; both versions use exactly the same trace.
  xymax <- max(abs(c(static_traces$x,static_traces$y,homes$x,homes$y)))+5
  gg <- ggplot() +
    geom_path(data=static_traces,aes(x,y,group=juggler,color=juggler),
              linewidth=.65,alpha=.65) +
    geom_point(data=beat_dots,aes(x,y,color=juggler),size=.7,alpha=.85) +
    geom_point(data=homes,aes(x,y),shape=3,color='#8392a7',size=2.4) +
    geom_path(data=disks,aes(x,y,group=interaction(frame,juggler),color=juggler),
              linewidth=.35,alpha=.5) +
    geom_segment(data=segments,aes(x=x,y=y,xend=xend,yend=yend),
                 linewidth=.5,color='#303b54',alpha=.75) +
    geom_point(data=moving,aes(x,y,color=juggler),size=4) +
    geom_text(data=moving,aes(x,y,label=juggler),size=2.35,color='white',fontface='bold') +
    scale_color_manual(values=colors,guide='none') +
    coord_fixed(xlim=c(-xymax,xymax),ylim=c(-xymax,xymax),expand=FALSE) +
    labs(title=paste0(n,'-person FEAST — ',direction,' — max pass ',sprintf('%.1f',max(throw_length)),' ft'),
         subtitle='Frame {current_frame}  |  small dots = positions at all 20 passing beats',
         caption='Crosses = home   •   Circles = 3-ft personal radius   •   Pass lines at beats only',
         x=NULL,y=NULL) +
    theme_void(base_size=12) +
    theme(plot.background=element_rect(fill='#f8f9fc',color=NA),
          panel.background=element_rect(fill='#f8f9fc',color=NA),
          plot.title=element_text(face='bold',size=15,hjust=.5,color='#243650'),
          plot.subtitle=element_text(hjust=.5,color='#53647e'),
          plot.caption=element_text(hjust=.5,color='#53647e',size=9)) +
    transition_manual(frame)
  out <- paste0('feast_n20_',direction,'_reconstructed_R.gif')
  gganimate::animate(gg,nframes=frames,fps=12,width=800,height=850,
                     renderer=gganimate::gifski_renderer(out))
  cat('Created',out,'\n')
}
make_frames(FALSE)
make_frames(TRUE)
